    +(ev[3]||ev[4]||TLPH[ev[1]]?`<div class="gos">${ev[3]?`<button class="btn" data-ev="${i}">${tr("Ver no mapa","See it on the map","Op de kaart")}</button>`:""}${ev[4]?`<button class="btn ghost" data-st="${ev[4]}">${tr("A história","The story","Het verhaal")}</button>`:""}${TLPH[ev[1]]?`<button class="btn ghost" data-tph="${ev[1]}">${tr("Fotografias","Photos","Foto's")}</button>`:""}</div>`:"");
