function storyCard(h){const pt=lang==="pt",R=REL[h.r],ti=TL.findIndex(e=>e[4]===h.id),src=T(h.s);
  return `<article class="story" id="st-${h.id}" style="--rc:${R.c}"${h.p?` data-pin="${h.p}"`:""}>
    <div class="sm">${relTag(h.r)}<time>${esc(T(h.d))}</time>${h.p?`<span class="where">${esc(T(HP[h.p].t))}</span>`:""}</div>
    <h3>${esc(T(h.t))}</h3><p>${T(h.x)}</p><p class="ss">${src.includes(";")?(tr("Fontes","Sources","Bronnen")):(tr("Fonte","Source","Bron"))}: ${esc(src)}</p>
    ${h.p||ti>=0||h.manu||h.ext||h.view?`<div class="sa">${h.p?`<button data-hpin="${h.p}" data-hs="${h.id}">${tr("Ver no mapa","See on the map","Bekijk op de kaart")}</button>`:""}${ti>=0?`<button data-tli="${ti}">${tr("Na linha do tempo","On the timeline","Op de tijdlijn")}</button>`:""}${h.manu?`<button data-manu2="${h.manu}">${tr("Na planta manuscrita","On the manuscript plan","Op de handgetekende plattegrond")}</button>`:""}${h.view?`<button data-view="${h.view}">${tr("Ver a vista de 1620","See the 1620 view","Bekijk het gezicht van 1620")}</button>`:""}${h.ext?`<a href="${h.ext[0]}" target="_blank" rel="noopener">${esc(T(h.ext[1]))} ↗</a>`:""}</div>`:""}
  </article>`}
function renderStories(){const pt=lang==="pt";
  $("#rels").innerHTML=Object.values(REL).map(r=>`<span class="rel" style="--rc:${r.c}">${esc(T(r))}</span><span>${esc(T(r.d))}</span>`).join("");
  const cnt=g=>HS.filter(h=>h.g===g).length;
  $("#hfilters").innerHTML=[["all",{pt:"Todas",en:"All",nl:"Alles"}],...HGROUPS].map(([k,l])=>`<button data-hf="${k}" aria-pressed="${k===hgf}">${esc(T(l))} <small>${k==="all"?HS.length:cnt(k)}</small></button>`).join("");
  $$("#hfilters button").forEach(b=>b.onclick=()=>{hgf=b.dataset.hf;renderStories()});
  $("#stories").innerHTML=HGROUPS.filter(([k])=>hgf==="all"||hgf===k).map(([k,l])=>`<h3 class="sgh">${esc(T(l))}</h3>`+HS.filter(h=>h.g===k).map(storyCard).join("")).join("");
  $$("#stories [data-hpin]").forEach(b=>b.onclick=()=>{const P=HP[b.dataset.hpin];hsFocus=b.dataset.hs;openAt("hist",P.tab,P.id)});
  $$("#stories [data-tli]").forEach(b=>b.onclick=()=>goTL(+b.dataset.tli));
  $$("#stories [data-manu2]").forEach(b=>b.onclick=()=>openAt("manu","manu",b.dataset.manu2));
  $$("#stories [data-view]").forEach(b=>b.onclick=()=>{const a=b.dataset.view.split(",");openAt(a[0],a[1])});
  $("#disp").innerHTML=DISPUTES.map(r=>`<tr><td>${esc(T(r[0]))}</td><td>${esc(T(r[1]))}</td><td>${esc(T(r[2]))}</td></tr>`).join("");
  $("#hsrc").innerHTML=HSRC.map(([t,u])=>u?`<li><a href="${u}" target="_blank" rel="noopener">${esc(t)}</a></li>`:`<li>${esc(t)}</li>`).join("");
  observeStories()}
function observeStories(){if(storyIO)storyIO.disconnect();lastStory=null;
  storyIO=new IntersectionObserver(es=>{if(!wide())return;es.forEach(e=>{if(!e.isIntersecting)return;const el=e.target;if(el===lastStory)return;if(Date.now()-userTouch<2500)return;lastStory=el;
    $$(".story.cur").forEach(c=>c.classList.remove("cur"));el.classList.add("cur");
    const P=HP[el.dataset.pin];hsFocus=el.id.slice(3);
    if(cur.scene==="hist"&&cur.tab===P.tab){if(sel===P.id){const it=cur.items.find(i=>i.key===P.id);if(it)renderStrip(it)}else select(P.id,{fly:true,soft:true})}
    else{opt.hi=null;opt.iso=null;loadTab("hist",P.tab,{select:P.id,soft:true})}})},{rootMargin:"-30% 0px -62% 0px"});
  $$(".story[data-pin]").forEach(c=>storyIO.observe(c))}
function flash(el){el.classList.remove("flash");void el.offsetWidth;el.classList.add("flash")}
function goStory(id){if(!id)return;
  if(!wide()&&$("#stagecol").classList.contains("open")){$("#stagecol").classList.remove("open");document.body.classList.remove("lock")}
  showView("historias");
  if(hgf!=="all"&&!HS.some(h=>h.id===id&&h.g===hgf)){hgf="all";renderStories()}
  const el=document.getElementById("st-"+id);if(!el)return;requestAnimationFrame(()=>requestAnimationFrame(()=>{el.scrollIntoView({behavior:reduce?"auto":"smooth",block:"start"});flash(el)}))}
function goTL(i){showView("tempo");const ev=$$("#tlrow .ev")[i];if(!ev)return;
  const tl=$("#tl");tl.scrollTo({left:Math.max(0,ev.offsetLeft-tl.clientWidth/2+68),behavior:reduce?"auto":"smooth"});flash(ev.querySelector(".cd"))}

