function syncMode(){}
function setMode(m){if(m!=="dark"&&m!=="auto")m="light";root.dataset.mode=m;try{localStorage.setItem("fdr-mode",m)}catch(_){}}
new MutationObserver(syncMode).observe(root,{attributes:true,attributeFilter:["data-theme","data-mode"]});
try{matchMedia("(prefers-color-scheme: dark)").addEventListener("change",syncMode)}catch(_){}
